import{c as s,Q as a,j as e,m as t}from"./chunks/framework.DOi4mjdC.js";const h=JSON.parse('{"title":"Transpose Tiling","description":"","frontmatter":{},"headers":[{"level":1,"title":"Transpose Tiling","slug":"transpose-tiling"},{"level":2,"title":"功能说明","slug":"功能说明"},{"level":2,"title":"函数原型","slug":"函数原型"},{"level":2,"title":"参数说明","slug":"参数说明"},{"level":2,"title":"返回值说明","slug":"返回值说明"},{"level":2,"title":"约束说明","slug":"约束说明"},{"level":2,"title":"调用示例","slug":"调用示例"}],"relativePath":"api/SIMD-API/高阶API/张量变换/Transpose-Tiling.md","filePath":"api/SIMD-API/高阶API/张量变换/Transpose-Tiling.md"}'),i={name:"api/SIMD-API/高阶API/张量变换/Transpose-Tiling.md"};function p(l,n,o,c,d,r){return a(),e("div",null,[...n[0]||(n[0]=[t(`<h1 id="transpose-tiling" tabindex="-1">Transpose Tiling <a class="header-anchor" href="#transpose-tiling" aria-label="Permalink to &quot;Transpose Tiling&quot;">​</a></h1><h2 id="功能说明" tabindex="-1">功能说明 <a class="header-anchor" href="#功能说明" aria-label="Permalink to &quot;功能说明&quot;">​</a></h2><p>用于获取Transpose Tiling参数。</p><h2 id="函数原型" tabindex="-1">函数原型 <a class="header-anchor" href="#函数原型" aria-label="Permalink to &quot;函数原型&quot;">​</a></h2><div class="note custom-block github-alert"><p class="custom-block-title">说明</p><p>GetConfusionTransposeMaxMinTmpSize、GetConfusionTransposeTilingInfo、GetConfusionTransposeOnlyTilingInfo接口废弃，并将在后续版本移除，请不要使用该接口。请使用GetTransposeMaxMinTmpSize、GetTransposeTilingInfo接口。</p></div><ul><li><p>获取最小临时空间大小</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>void GetTransposeMaxMinTmpSize(const ge::Shape&amp; srcShape, const uint32_t typeSize, const uint32_t transposeTypeIn, uint32_t&amp; maxValue, uint32_t&amp; minValue)</span></span></code></pre></div><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>void GetConfusionTransposeMaxMinTmpSize(const ge::Shape&amp; srcShape, const uint32_t typeSize, const uint32_t transposeTypeIn, uint32_t&amp; maxValue, uint32_t&amp; minValue)</span></span></code></pre></div></li><li><p>获取Transpose Tiling</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>void GetTransposeTilingInfo(const ge::Shape&amp; srcShape, const uint32_t stackBufferSize, const uint32_t typeSize, const uint32_t transposeTypeIn, optiling::ConfusionTransposeTiling&amp; tiling)</span></span></code></pre></div><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>void GetTransposeTilingInfo(const ge::Shape&amp; srcShape, const uint32_t stackBufferSize, const uint32_t typeSize, const uint32_t transposeTypeIn, AscendC::tiling::ConfusionTransposeTiling&amp; tiling)</span></span></code></pre></div><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>void GetConfusionTransposeOnlyTilingInfo(const ge::Shape&amp; srcShape, const uint32_t stackBufferSize, const uint32_t typeSize, optiling::ConfusionTransposeTiling&amp; tiling)</span></span></code></pre></div><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>void GetConfusionTransposeOnlyTilingInfo(const ge::Shape&amp; srcShape, const uint32_t stackBufferSize, const uint32_t typeSize, AscendC::tiling::ConfusionTransposeTiling&amp; tiling)</span></span></code></pre></div><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>void GetConfusionTransposeTilingInfo(const ge::Shape&amp; srcShape, const uint32_t stackBufferSize, const uint32_t typeSize, const uint32_t transposeTypeIn, optiling::ConfusionTransposeTiling&amp; tiling)</span></span></code></pre></div><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>void GetConfusionTransposeTilingInfo(const ge::Shape&amp; srcShape, const uint32_t stackBufferSize, const uint32_t typeSize, const uint32_t transposeTypeIn, AscendC::tiling::ConfusionTransposeTiling&amp; tiling)</span></span></code></pre></div></li></ul><h2 id="参数说明" tabindex="-1">参数说明 <a class="header-anchor" href="#参数说明" aria-label="Permalink to &quot;参数说明&quot;">​</a></h2><p><strong>表 1</strong> <strong>GetTransposeMaxMinTmpSize接口参数说明</strong></p><table tabindex="0"><thead><tr><th>参数名</th><th>输入/输出</th><th>含义</th></tr></thead><tbody><tr><td>srcShape</td><td>输入</td><td>输入Tensor的shape信息，具体srcShape传入格式为： 场景1：[B, N, S, H/N] 场景2：[B, N, S, H/N] 场景3：[B, N, S, H/N] 场景4：[B, N, S, H/N] 场景5：[B, N, S, H/N] 场景6：[B, N, S, H/N] 场景7：[H, W] 场景13:[H, W]或者[N, H, W]，仅支持Ascend 950PR/Ascend 950DT。 场景14:[N, H, W]，仅支持Ascend 950PR/Ascend 950DT。 场景15:[N, H, W]，仅支持Ascend 950PR/Ascend 950DT。 场景16:[H, W]，仅支持Ascend 950PR/Ascend 950DT。</td></tr><tr><td>typeSize</td><td>输入</td><td>输入的数据类型大小，单位为字节。比如输入的数据类型为half，此处应传入2。</td></tr><tr><td>transposeTypeIn</td><td>输入</td><td>选择数据排布及reshape的类型，根据输入数字选择对应的场景，参数范围为[1,7]。针对Ascend 950PR/Ascend 950DT，该参数取值范围为[1, 7]和[13, 16]。 场景1（NZ2ND，1、2轴互换）：1 场景2（NZ2NZ，1、2轴互换）：2 场景3（NZ2NZ，尾轴切分）：3 场景4（NZ2ND，尾轴切分）：4 场景5（NZ2ND，尾轴合并）：5 场景6（NZ2NZ，尾轴合并）：6 场景7（二维转置）：7 场景13 （二维转置或者三维转置中后两维转置）：13，仅支持Ascend 950PR/Ascend 950DT。 场景14 （三维转置中第一维和第二维互换）：14，仅支持Ascend 950PR/Ascend 950DT。 场景15 （三维转置中第一维和第三维互换）：15，仅支持Ascend 950PR/Ascend 950DT。 场景16 （使用交织指令进行两维ND2NZ转置） :16，仅支持Ascend 950PR/Ascend 950DT。</td></tr><tr><td>maxValue</td><td>输出</td><td>Transpose接口能完成计算所需的最大临时空间大小，超出该值的空间不会被该接口使用。在最小临时空间-最大临时空间范围内，随着临时空间增大，kernel侧接口计算性能会有一定程度的优化提升。为了达到更好的性能，开发者可以根据实际的内存使用情况进行空间预留/申请。 说明： maxValue仅作为参考值，有可能大于Unified Buffer剩余空间的大小，该场景下，开发者需要根据Unified Buffer剩余空间的大小来选取合适的临时空间大小。</td></tr><tr><td>minValue</td><td>输出</td><td>Transpose接口能完成计算所需最小临时空间大小。为保证功能正确，接口计算时预留/申请的临时空间不能小于该数值。</td></tr></tbody></table><p><strong>表 2</strong> <strong>GetTransposeTilingInfo接口参数列表</strong></p><table tabindex="0"><thead><tr><th>参数名</th><th>输入/输出</th><th>含义</th></tr></thead><tbody><tr><td>srcShape</td><td>输入</td><td>输入的shape信息，具体srcShape传入格式为： 场景1：[B, N, S, H/N] 场景2：[B, N, S, H/N] 场景3：[B, N, S, H/N] 场景4：[B, N, S, H/N] 场景5：[B, N, S, H/N] 场景6：[B, N, S, H/N] 场景7：[H, W] 场景13：[H, W]或者[N, H, W]，仅支持Ascend 950PR/Ascend 950DT。 场景14:[N, H, W]，仅支持Ascend 950PR/Ascend 950DT。 场景15:[N, H, W]，仅支持Ascend 950PR/Ascend 950DT。 场景16 ：[H, W]，仅支持Ascend 950PR/Ascend 950DT。</td></tr><tr><td>stackBufferSize</td><td>输入</td><td>可供Transpose接口计算的空间大小，单位Byte。</td></tr><tr><td>typeSize</td><td>输入</td><td>输入的数据类型大小，单位为字节。比如输入的数据类型为half，此处应传入2。</td></tr><tr><td>transposeTypeIn</td><td>输入</td><td>选择数据排布及reshape的类型，根据输入数字选择对应的场景，参数范围为[1,7]。Ascend 950PR/Ascend 950DT，该参数取值范围为[1, 7]和[13, 16]。 场景1（NZ2ND，1、2轴互换）：1 场景2（NZ2NZ，1、2轴互换）：2 场景3（NZ2NZ，尾轴切分）：3 场景4（NZ2ND，尾轴切分）：4 场景5（NZ2ND，尾轴合并）：5 场景6（NZ2NZ，尾轴合并）：6 场景7（二维转置）：7 场景13 （二维转置或者三维转置中后两维转置）：13，仅支持Ascend 950PR/Ascend 950DT。 场景14 （三维转置中第一维和第二维互换）：14，仅支持Ascend 950PR/Ascend 950DT。 场景15 （三维转置中第一维和第三维互换）：15，仅支持Ascend 950PR/Ascend 950DT。 场景16（使用交织指令进行两维ND2NZ转置）：16，仅支持Ascend 950PR/Ascend 950DT。</td></tr><tr><td>tiling</td><td>输出</td><td>输入数据的切分信息。</td></tr></tbody></table><h2 id="返回值说明" tabindex="-1">返回值说明 <a class="header-anchor" href="#返回值说明" aria-label="Permalink to &quot;返回值说明&quot;">​</a></h2><p>无</p><h2 id="约束说明" tabindex="-1">约束说明 <a class="header-anchor" href="#约束说明" aria-label="Permalink to &quot;约束说明&quot;">​</a></h2><p>无</p><h2 id="调用示例" tabindex="-1">调用示例 <a class="header-anchor" href="#调用示例" aria-label="Permalink to &quot;调用示例&quot;">​</a></h2><p>如下样例介绍了使用Transpose高阶API时host侧获取Tiling参数的流程以及该参数如何在kernel侧使用。样例中为场景1，输入Tensor的shape大小为[1, 2, 64, 32]，输入的数据类型为half。</p><ol><li><p>将ConfusionTransposeTiling结构体参数增加至TilingData结构体，作为TilingData结构体的一个字段。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>BEGIN_TILING_DATA_DEF(TilingData)               // 注册一个tiling的类，以tiling的名字作为入参</span></span>
<span class="line"><span>  TILING_DATA_FIELD_DEF(uint32_t, tileNum);     // 添加tiling字段，每个核上总计算数据分块个数</span></span>
<span class="line"><span>  ...                                           // 添加其他tiling字段</span></span>
<span class="line"><span>  TILING_DATA_FIELD_DEF_STRUCT(ConfusionTransposeTiling, confusionTransposeTilingData); // 将ConfusionTransposeTiling结构体参数增加至TilingData结构体</span></span>
<span class="line"><span>END_TILING_DATA_DEF;</span></span></code></pre></div></li><li><p>Tiling实现函数中，根据输入shape、可供计算的空间大小(stackBufferSize)等信息获取Transpose kernel侧接口所需tiling参数。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>namespace optiling {</span></span>
<span class="line"><span>const uint32_t NUM_BLOCKS = 8;</span></span>
<span class="line"><span>const uint32_t TILE_NUM = 8;</span></span>
<span class="line"><span>static ge::graphStatus TilingFunc(gert::TilingContext* context)</span></span>
<span class="line"><span>{</span></span>
<span class="line"><span>    TilingData tiling;</span></span>
<span class="line"><span>    uint32_t totalLength = context-&gt;GetInputTensor(0)-&gt;GetShapeSize();</span></span>
<span class="line"><span>    context-&gt;SetBlockDim(NUM_BLOCKS);</span></span>
<span class="line"><span>    tiling.set_tileNum(TILE_NUM);</span></span>
<span class="line"><span>    // 设置其他Tiling参数</span></span>
<span class="line"><span>    ... </span></span>
<span class="line"><span>    std::vector&lt;int64_t&gt; shapeVec = {1, 2, 64, 32};</span></span>
<span class="line"><span>    ge::Shape srcShape(shapeVec);</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    uint32_t transposeTypeIn = 1;</span></span>
<span class="line"><span>    uint32_t maxValue = 0;</span></span>
<span class="line"><span>    uint32_t minValue = 0;</span></span>
<span class="line"><span>    AscendC::GetTransposeMaxMinTmpSize(srcShape, sizeof(half), transposeTypeIn, maxValue, minValue);</span></span>
<span class="line"><span>    // 本样例中仅作为样例说明，获取最小值并传入，来保证功能正确，开发者可以根据需要传入合适的空间大小</span></span>
<span class="line"><span>    const uint32_t stackBufferSize = minValue;</span></span>
<span class="line"><span>    // 获取Transpose Tiling参数</span></span>
<span class="line"><span>    AscendC::GetTransposeTilingInfo(srcShape, stackBufferSize, sizeof(half), transposeTypeIn, tiling.confusionTransposeTilingData); </span></span>
<span class="line"><span>     ... // 其他逻辑</span></span>
<span class="line"><span>    tiling.SaveToBuffer(context-&gt;GetRawTilingData()-&gt;GetData(), context-&gt;GetRawTilingData()-&gt;GetCapacity());</span></span>
<span class="line"><span>    context-&gt;GetRawTilingData()-&gt;SetDataSize(tiling.GetDataSize());</span></span>
<span class="line"><span>    context-&gt;SetTilingKey(1);</span></span>
<span class="line"><span>    return ge::GRAPH_SUCCESS;</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span>} // namespace optiling</span></span></code></pre></div></li><li><p>对应的kernel侧通过在核函数中调用GET_TILING_DATA获取TilingData，继而将TilingData中的ConfusionTransposeTiling信息传入Transpose接口参与计算。完整的kernel侧样例请参考<a href="./Transpose-96.html">Transpose</a>。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>extern &quot;C&quot; __global__ __aicore__ void  func_custom(GM_ADDR src_gm, GM_ADDR dst_gm, GM_ADDR workspace, GM_ADDR tiling)                     </span></span>
<span class="line"><span>{   </span></span>
<span class="line"><span>    GET_TILING_DATA(TilingData, tiling);                                                                                      </span></span>
<span class="line"><span>    KernelTranspose&lt;half&gt; op;                                         </span></span>
<span class="line"><span>    op.Init(src_gm, dst_gm, TilingData.confusionTransposeTilingData); </span></span>
<span class="line"><span>    op.Process();                                                                                </span></span>
<span class="line"><span>}</span></span></code></pre></div></li></ol>`,18)])])}const u=s(i,[["render",p]]);export{h as __pageData,u as default};
